CREATE TABLE usuarios (id_usuario integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre varchar NOT NULL, apodo varchar, email varchar NOT NULL UNIQUE, contrasena varchar NOT NULL, tema varchar DEFAULT 'Claro', verificado boolean DEFAULT false, token_verificacion varchar, token_verificacion_expira timestamp, token_recuperacion varchar, token_recuperacion_expira timestamp, foto_perfil text, biografia varchar, telefono varchar, telefono_verificado_en timestamptz, telefono_canal varchar, canal_preferido varchar DEFAULT 'correo', notif_solicitudes boolean DEFAULT true, notif_publicaciones boolean DEFAULT true, politicas_aceptadas_en timestamptz, rol varchar DEFAULT 'usuario', suspendido_hasta timestamptz, baneado_en timestamptz, motivo_sancion text, eliminado_en timestamptz, notif_recordatorio boolean DEFAULT true, ultimo_recordatorio date, memoria_activa boolean DEFAULT true);
CREATE TABLE publicaciones (id_publicacion integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_usuario integer NOT NULL REFERENCES usuarios ON DELETE CASCADE, sueno_texto text NOT NULL, titulo varchar, interpretacion_ia text, estado varchar DEFAULT 'procesando', creado_en timestamptz DEFAULT now(), emocion varchar, tipo_sueno varchar, tema varchar);
CREATE TABLE medios_publicacion (id_medio integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_publicacion integer NOT NULL REFERENCES publicaciones ON DELETE CASCADE, tipo varchar NOT NULL, url text NOT NULL, orden smallint DEFAULT 0, prompt_ia text, creado_en timestamptz DEFAULT now());
CREATE TABLE corazones (id_usuario integer NOT NULL, id_publicacion integer NOT NULL REFERENCES publicaciones ON DELETE CASCADE, creado_en timestamptz DEFAULT now(), reaccion varchar DEFAULT 'corazon', PRIMARY KEY (id_usuario, id_publicacion));
CREATE TABLE comentarios (id_comentario integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_publicacion integer NOT NULL REFERENCES publicaciones ON DELETE CASCADE, id_usuario integer NOT NULL, contenido text NOT NULL, creado_en timestamptz DEFAULT now());
CREATE TABLE sesiones (sid varchar NOT NULL PRIMARY KEY, sess json NOT NULL, expire timestamp NOT NULL);
